package vn.edu.library.ui;

import vn.edu.library.data.Database;
import vn.edu.library.domain.UserSession;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.io.IOException;
import java.nio.file.*;
import java.sql.*;
import java.util.UUID;

public final class DocumentsPanel extends JPanel {
    private final UserSession session;
    private final JTextField search=new JTextField(25);
    private final JLabel status=new JLabel(" ");
    private final DefaultTableModel model=new DefaultTableModel(){@Override public boolean isCellEditable(int r,int c){return false;}};
    private final JTable table=new JTable(model);
    public DocumentsPanel(UserSession session){this.session=session;setLayout(new BorderLayout(0,16));setBackground(UiStyle.CANVAS);setBorder(new EmptyBorder(27,30,24,30));add(header(),BorderLayout.NORTH);table.setRowHeight(33);table.setAutoCreateRowSorter(true);table.setFillsViewportHeight(true);JScrollPane sc=new JScrollPane(table);sc.setBorder(BorderFactory.createLineBorder(new Color(229,233,240)));add(sc,BorderLayout.CENTER);status.setForeground(UiStyle.MUTED);add(status,BorderLayout.SOUTH);load();}
    private JComponent header(){JPanel h=new JPanel(new BorderLayout(0,16));h.setOpaque(false);JPanel t=new JPanel();t.setOpaque(false);t.setLayout(new BoxLayout(t,BoxLayout.Y_AXIS));JLabel title=new JLabel("Tài liệu điện tử");title.setFont(title.getFont().deriveFont(Font.BOLD,25f));JLabel sub=new JLabel("Quản lý tài liệu PDF và tệp đọc trực tuyến cho độc giả đã đăng nhập.");sub.setForeground(UiStyle.MUTED);t.add(title);t.add(Box.createVerticalStrut(5));t.add(sub);h.add(t,BorderLayout.NORTH);search.putClientProperty("JTextField.placeholderText","Tiêu đề, tác giả, danh mục");JButton find=new JButton("Tìm kiếm"),refresh=new JButton("Làm mới"),add=new JButton("Thêm tài liệu"),edit=new JButton("Sửa"),archive=new JButton("Lưu trữ / khôi phục"),open=new JButton("Mở xem"),delete=new JButton("Xóa tài liệu");add.setBackground(UiStyle.BLUE);add.setForeground(Color.WHITE);find.addActionListener(e->load());refresh.addActionListener(e->{search.setText("");load();});search.addActionListener(e->load());add.addActionListener(e->editDocument(null));edit.addActionListener(e->editSelected());archive.addActionListener(e->toggleArchive());open.addActionListener(e->openSelected());delete.addActionListener(e->deleteSelected());JPanel c=new JPanel(new FlowLayout(FlowLayout.LEFT,7,0));c.setOpaque(false);for(JComponent x:new JComponent[]{search,find,refresh,add,edit,archive,open,delete})c.add(x);h.add(c,BorderLayout.SOUTH);return h;}
    private void load(){String term=search.getText().trim();String sql="SELECT d.document_id AS 'ID',d.title AS 'Tiêu đề',d.author_label AS 'Tác giả',d.category_label AS 'Danh mục',d.mime_type AS 'Định dạng',d.document_status AS 'Trạng thái',d.uploaded_at AS 'Ngày tải lên',s.full_name AS 'Người tải' FROM electronic_documents d JOIN staff_profiles s ON s.staff_id=d.uploaded_by WHERE (?='' OR d.title LIKE ? OR d.author_label LIKE ? OR d.category_label LIKE ?) ORDER BY d.uploaded_at DESC";try(Connection c=Database.getConnection();PreparedStatement q=c.prepareStatement(sql)){String p="%"+term+"%";q.setString(1,term);for(int i=2;i<=4;i++)q.setString(i,p);try(ResultSet rs=q.executeQuery()){ResultSetMetaData md=rs.getMetaData();model.setRowCount(0);model.setColumnCount(0);for(int i=1;i<=md.getColumnCount();i++)model.addColumn(md.getColumnLabel(i));while(rs.next()){Object[] a=new Object[md.getColumnCount()];for(int i=1;i<=a.length;i++)a[i-1]=rs.getObject(i);model.addRow(a);}}status.setText("Đang hiển thị "+model.getRowCount()+" tài liệu.");}catch(Exception ex){model.setRowCount(0);status.setText("Không tải được tài liệu: "+ex.getMessage());}}
    private void editSelected(){int view=table.getSelectedRow();if(view<0){message("Chọn tài liệu trước.",JOptionPane.INFORMATION_MESSAGE);return;}int row=table.convertRowIndexToModel(view);long id=Long.parseLong(model.getValueAt(row,0).toString());try(Connection c=Database.getConnection();PreparedStatement q=c.prepareStatement("SELECT * FROM electronic_documents WHERE document_id=?")){q.setLong(1,id);try(ResultSet rs=q.executeQuery()){if(rs.next())editDocument(new DocumentForm(rs));}}catch(Exception ex){message("Không mở được tài liệu: "+ex.getMessage(),JOptionPane.ERROR_MESSAGE);}}
    private void editDocument(DocumentForm current){boolean create=current==null;DocumentForm form=create?new DocumentForm():current;int result=JOptionPane.showConfirmDialog(this,form.panel,create?"Thêm tài liệu điện tử":"Cập nhật tài liệu điện tử",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE);if(result!=JOptionPane.OK_OPTION)return;String title=form.title.getText().trim();if(title.isBlank()){message("Tiêu đề là bắt buộc.",JOptionPane.WARNING_MESSAGE);return;}try{String storedPath=form.selectedFile==null?form.existingPath:copyToStorage(form.selectedFile);if(storedPath==null||storedPath.isBlank())throw new IllegalArgumentException("Chọn tệp PDF trước.");try(Connection c=Database.getConnection()){if(create){try(PreparedStatement q=c.prepareStatement("INSERT INTO electronic_documents(title,description,author_label,category_label,file_path,mime_type,uploaded_by) VALUES(?,?,?,?,?,'application/pdf',?)")){q.setString(1,title);q.setString(2,empty(form.description.getText()));q.setString(3,empty(form.author.getText()));q.setString(4,empty(form.category.getText()));q.setString(5,storedPath);q.setLong(6,staffId(c));q.executeUpdate();}}else{try(PreparedStatement q=c.prepareStatement("UPDATE electronic_documents SET title=?,description=?,author_label=?,category_label=?,file_path=? WHERE document_id=?")){q.setString(1,title);q.setString(2,empty(form.description.getText()));q.setString(3,empty(form.author.getText()));q.setString(4,empty(form.category.getText()));q.setString(5,storedPath);q.setLong(6,form.documentId);q.executeUpdate();}}}load();message("Đã lưu tài liệu. Tệp được lưu vào thư mục library-storage/documents.",JOptionPane.INFORMATION_MESSAGE);}catch(Exception ex){message("Không lưu được tài liệu: "+ex.getMessage(),JOptionPane.ERROR_MESSAGE);}}
    private String copyToStorage(Path source)throws IOException{if(!Files.isRegularFile(source)||!".pdf".equalsIgnoreCase(extension(source.getFileName().toString())))throw new IllegalArgumentException("Chỉ nhận tệp PDF hợp lệ.");if(Files.size(source)>50L*1024*1024)throw new IllegalArgumentException("Tệp không được vượt quá 50 MB.");validatePdf(source);Path dir=Path.of(System.getProperty("user.dir"),"library-storage","documents");Files.createDirectories(dir);String filename=UUID.randomUUID()+".pdf";Files.copy(source,dir.resolve(filename),StandardCopyOption.REPLACE_EXISTING);return "documents/"+filename;}
    private void validatePdf(Path path)throws IOException{try(java.io.RandomAccessFile pdf=new java.io.RandomAccessFile(path.toFile(),"r")){byte[] header=new byte[5];if(pdf.read(header)!=5||!"%PDF-".equals(new String(header,java.nio.charset.StandardCharsets.US_ASCII)))throw new IllegalArgumentException("Tệp không có chữ ký định dạng PDF.");long length=pdf.length();int size=(int)Math.min(2048,length);pdf.seek(Math.max(0,length-size));byte[] tail=new byte[size];pdf.readFully(tail);if(!new String(tail,java.nio.charset.StandardCharsets.ISO_8859_1).contains("%%EOF"))throw new IllegalArgumentException("Tệp PDF chưa hoàn chỉnh hoặc bị hỏng.");}}
    private String extension(String name){int i=name.lastIndexOf('.');return i<0?"":name.substring(i);}
    private void chooseFile(JTextField field,DocumentForm form){JFileChooser chooser=new JFileChooser();chooser.setDialogTitle("Chọn tài liệu PDF");chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("PDF (*.pdf)","pdf"));if(chooser.showOpenDialog(this)==JFileChooser.APPROVE_OPTION){form.selectedFile=chooser.getSelectedFile().toPath();field.setText(form.selectedFile.getFileName().toString());}}
    private void toggleArchive(){int view=table.getSelectedRow();if(view<0){message("Chọn tài liệu trước.",JOptionPane.INFORMATION_MESSAGE);return;}int row=table.convertRowIndexToModel(view);long id=Long.parseLong(model.getValueAt(row,0).toString());String state=model.getValueAt(row,5).toString();String next="ACTIVE".equals(state)?"ARCHIVED":"ACTIVE";if(JOptionPane.showConfirmDialog(this,"Chuyển tài liệu thành "+next+"?","Xác nhận",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try(Connection c=Database.getConnection();PreparedStatement q=c.prepareStatement("UPDATE electronic_documents SET document_status=? WHERE document_id=?")){q.setString(1,next);q.setLong(2,id);q.executeUpdate();load();}catch(Exception ex){message("Không đổi được trạng thái: "+ex.getMessage(),JOptionPane.ERROR_MESSAGE);}}
    private void openSelected(){int view=table.getSelectedRow();if(view<0){message("Chọn tài liệu trước.",JOptionPane.INFORMATION_MESSAGE);return;}int row=table.convertRowIndexToModel(view);long id=Long.parseLong(model.getValueAt(row,0).toString());try(Connection c=Database.getConnection();PreparedStatement q=c.prepareStatement("SELECT file_path FROM electronic_documents WHERE document_id=? AND document_status='ACTIVE'")){q.setLong(1,id);try(ResultSet rs=q.executeQuery()){if(!rs.next())throw new IllegalArgumentException("Tài liệu đã lưu trữ hoặc không tồn tại.");Path path=Path.of(System.getProperty("user.dir"),"library-storage",rs.getString(1));if(!Files.exists(path))throw new IOException("Không tìm thấy tệp: "+path);Desktop.getDesktop().open(path.toFile());}}catch(Exception ex){message("Không mở được tệp: "+ex.getMessage(),JOptionPane.ERROR_MESSAGE);}}
    private void deleteSelected(){int view=table.getSelectedRow();if(view<0){message("Chọn tài liệu cần xóa.",JOptionPane.INFORMATION_MESSAGE);return;}int row=table.convertRowIndexToModel(view);long id=Long.parseLong(model.getValueAt(row,0).toString());String title=model.getValueAt(row,1).toString();if(JOptionPane.showConfirmDialog(this,"Xóa vĩnh viễn tài liệu '"+title+"' và tệp PDF? Việc này chỉ được phép khi chưa có lịch sử đọc cần giữ.","Xác nhận xóa",JOptionPane.YES_NO_OPTION,JOptionPane.WARNING_MESSAGE)!=JOptionPane.YES_OPTION)return;Path quarantine=null,source=null;boolean databaseDeleted=false;try{String stored;try(Connection c=Database.getConnection();PreparedStatement q=c.prepareStatement("SELECT file_path FROM electronic_documents WHERE document_id=? FOR UPDATE")){q.setLong(1,id);try(ResultSet rs=q.executeQuery()){if(!rs.next())throw new IllegalArgumentException("Tài liệu không còn tồn tại.");stored=rs.getString(1);}}Path root=Path.of(System.getProperty("user.dir"),"library-storage").toAbsolutePath().normalize();Path docs=root.resolve("documents").normalize();source=root.resolve(stored).normalize();if(!source.startsWith(docs))throw new IllegalArgumentException("Đường dẫn tệp nằm ngoài kho tài liệu hợp lệ.");if(Files.exists(source)){quarantine=docs.resolve(".delete-"+UUID.randomUUID()+".pdf");Files.move(source,quarantine,StandardCopyOption.REPLACE_EXISTING);}try(Connection c=Database.getConnection()){c.setAutoCommit(false);try(PreparedStatement q=c.prepareStatement("DELETE FROM electronic_documents WHERE document_id=?")){q.setLong(1,id);if(q.executeUpdate()!=1)throw new IllegalArgumentException("Tài liệu vừa được xử lý ở nơi khác.");c.commit();databaseDeleted=true;}catch(Exception ex){c.rollback();if(quarantine!=null&&Files.exists(quarantine))Files.move(quarantine,source,StandardCopyOption.REPLACE_EXISTING);throw ex;}finally{c.setAutoCommit(true);}}if(quarantine!=null)Files.deleteIfExists(quarantine);load();message("Đã xóa tài liệu và tệp.",JOptionPane.INFORMATION_MESSAGE);}catch(Exception ex){if(!databaseDeleted&&quarantine!=null&&source!=null&&Files.exists(quarantine)){try{Files.move(quarantine,source,StandardCopyOption.REPLACE_EXISTING);}catch(IOException restore){ex.addSuppressed(restore);}}message("Không xóa được tài liệu: "+ex.getMessage(),JOptionPane.ERROR_MESSAGE);}}
    private long staffId(Connection c)throws SQLException{try(PreparedStatement q=c.prepareStatement("SELECT staff_id FROM accounts WHERE account_id=? AND staff_id IS NOT NULL")){q.setLong(1,session.accountId());try(ResultSet rs=q.executeQuery()){if(!rs.next())throw new SQLException("Tài khoản chưa liên kết nhân viên.");return rs.getLong(1);}}}
    private String empty(String s){return s==null||s.trim().isEmpty()?null:s.trim();}
    private void message(String s,int t){JOptionPane.showMessageDialog(this,s,"Tài liệu điện tử",t);}
    private final class DocumentForm{final JPanel panel=new JPanel(new GridBagLayout());final JTextField title=new JTextField(22),author=new JTextField(22),category=new JTextField(22),file=new JTextField(22);final JTextArea description=new JTextArea(4,22);Path selectedFile;String existingPath;long documentId;DocumentForm(){build();}DocumentForm(ResultSet r)throws SQLException{documentId=r.getLong("document_id");title.setText(r.getString("title"));author.setText(r.getString("author_label"));category.setText(r.getString("category_label"));description.setText(r.getString("description"));existingPath=r.getString("file_path");file.setText(existingPath);build();}void build(){JButton choose=new JButton("Chọn PDF");choose.addActionListener(e->chooseFile(file,this));panel.setBorder(new EmptyBorder(8,4,8,4));int y=0;y=row(y,"Tiêu đề *",title);y=row(y,"Tác giả",author);y=row(y,"Danh mục",category);y=row(y,"Mô tả",new JScrollPane(description));row(y,"Tệp PDF",file);GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(4,5,4,5);c.gridy=y;c.gridx=2;c.fill=GridBagConstraints.HORIZONTAL;panel.add(choose,c);}int row(int y,String label,JComponent input){GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(4,5,4,5);c.gridy=y;c.gridx=0;c.anchor=GridBagConstraints.WEST;panel.add(new JLabel(label),c);c.gridx=1;c.weightx=1;c.fill=GridBagConstraints.HORIZONTAL;panel.add(input,c);return y+1;}}
}
